import{_ as i,H as s,f as t,i as a}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"AGENTS.md","description":"","frontmatter":{},"headers":[{"level":2,"title":"Repository Overview","slug":"repository-overview","link":"#repository-overview","children":[]},{"level":2,"title":"Structure","slug":"structure","link":"#structure","children":[]},{"level":2,"title":"File Naming Convention","slug":"file-naming-convention","link":"#file-naming-convention","children":[]},{"level":2,"title":"Course PDF Conversion","slug":"course-pdf-conversion","link":"#course-pdf-conversion","children":[]},{"level":2,"title":"Local Preview and Build","slug":"local-preview-and-build","link":"#local-preview-and-build","children":[]},{"level":2,"title":"Git Workflow","slug":"git-workflow","link":"#git-workflow","children":[]}],"relativePath":"AGENTS.md","filePath":"AGENTS.md","lastUpdated":1795450155000}'),n={name:"AGENTS.md"};function o(r,e,l,d,p,c){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="agents-md" tabindex="-1">AGENTS.md <a class="header-anchor" href="#agents-md" aria-label="Permalink to &quot;AGENTS.md&quot;">​</a></h1><p>This file provides guidance to Codex (Codex.ai/code) when working with code in this repository.</p><h2 id="repository-overview" tabindex="-1">Repository Overview <a class="header-anchor" href="#repository-overview" aria-label="Permalink to &quot;Repository Overview&quot;">​</a></h2><p>This is a personal knowledge/note repository containing Markdown documents from various technical courses, published as a VitePress site (config in <code>.vitepress/</code>, helper scripts in <code>scripts/</code>).</p><h2 id="structure" tabindex="-1">Structure <a class="header-anchor" href="#structure" aria-label="Permalink to &quot;Structure&quot;">​</a></h2><p>Notes are organized into course directories at the top level:</p><ul><li><strong>左耳听风</strong> — Software engineering, distributed systems, programming paradigms, leadership (239 files)</li><li><strong>许式伟的架构课</strong> — Software architecture (178 files)</li><li><strong>数据结构与算法之美</strong> — Data structures and algorithms (156 files)</li><li><strong>MySQL实战45讲</strong> — MySQL/InnoDB practical guide (96 files)</li><li><strong>Java业务开发常见错误100例</strong> — Common Java development pitfalls (93 files)</li><li><strong>Redis源码剖析与实战</strong> — Redis source code analysis (93 files)</li><li><strong>容器实战高手课</strong> — Container/containerization (61 files)</li><li><strong>DDD实战课</strong> — Domain-Driven Design (51 files)</li><li><strong>RAG系统实战课</strong> — RAG system practical course (58 files)</li><li><strong>LLM自主智能体应用实战课</strong> — LLM autonomous agent applications (52 files)</li><li><strong>Codex企业级全链路开发实战</strong> — Codex enterprise development (102 files)</li><li><strong>Codex企业级老项目改造实战</strong> — Codex legacy project refactoring (58 files)</li><li><strong>Codex工程化实战</strong> — Codex engineering practices (95 files)</li><li><strong>从0开始构建AgentHarness</strong> — Building AgentHarness from scratch (44 files)</li><li><strong>深入拆解消息队列47讲</strong> — Message queue internals (24 files; source PDFs for lectures 19, 23, 24–47 are missing or empty)</li></ul><p>There are also a few standalone Markdown files at the root (e.g., <code>二叉树.md</code>, <code>网站 Https 化.md</code>, <code>Oh My Zsh 是什么.md</code>).</p><h2 id="file-naming-convention" tabindex="-1">File Naming Convention <a class="header-anchor" href="#file-naming-convention" aria-label="Permalink to &quot;File Naming Convention&quot;">​</a></h2><p>Files follow a numbered pattern, e.g., <code>01-标题.md</code>, <code>02｜标题.md</code>, <code>开篇词｜标题.md</code>, <code>结束语｜标题.md</code>. Delimiters between number and title vary (<code>-</code>, <code>｜</code>, <code>-｜</code>).</p><h2 id="course-pdf-conversion" tabindex="-1">Course PDF Conversion <a class="header-anchor" href="#course-pdf-conversion" aria-label="Permalink to &quot;Course PDF Conversion&quot;">​</a></h2><p><code>scripts/convert-course-pdf.py</code> converts Geekbang course PDFs (one per lecture, named like <code>01｜标题.pdf</code>) into the repository&#39;s Markdown note format and extracts figures into <code>images/&lt;​lecture&gt;/</code>. It requires PyMuPDF (already installed in user site-packages; if missing run <code>/usr/bin/python3 -m pip install --user pymupdf</code>).</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Convert a whole course directory; output defaults to &lt;​repo root&gt;/&lt;​input dir name&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/convert-course-pdf.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads/课程目录名</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Fill in missing lectures later without touching existing files</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/convert-course-pdf.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads/课程目录名</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-existing</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Preview what would be generated</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/convert-course-pdf.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads/课程目录名</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span></code></pre></div><p>After converting, regenerate the sidebar and update the course count in <code>index.md</code> and <code>.vitepress/config.ts</code> to match the number printed by the sidebar script:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node_modules/.bin/tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/generate-sidebar.mts</span></span></code></pre></div><p>Known source limitations: overlong code lines are truncated in the source PDFs, inline bold cannot be extracted, reader comments are excluded by convention, and ~1KB empty PDFs are skipped and listed in the summary.</p><h2 id="local-preview-and-build" tabindex="-1">Local Preview and Build <a class="header-anchor" href="#local-preview-and-build" aria-label="Permalink to &quot;Local Preview and Build&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node_modules/.bin/vitepress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5173</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # preview at http://localhost:5173/note-website/</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">NODE_OPTIONS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">--max-old-space-size</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">12288</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node_modules/.bin/vitepress</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span></code></pre></div><p>Use the executables under <code>node_modules/.bin/</code> directly. Avoid <code>pnpm exec</code>: it once moved node_modules packages into <code>.ignored</code> and triggered network re-fetches.</p><p>The image plugin <code>.vitepress/vpre-plugin.ts</code> rewrites relative image paths to GitHub raw URLs (branch <code>note-website</code>) in production builds and keeps local paths in dev. Images of a new course are unavailable online until the course is pushed to GitHub.</p><h2 id="git-workflow" tabindex="-1">Git Workflow <a class="header-anchor" href="#git-workflow" aria-label="Permalink to &quot;Git Workflow&quot;">​</a></h2><ul><li>Branch: <code>note-website</code> (current; GitHub raw image URLs point to this branch), <code>main</code> (default)</li><li>Commit message style: <code>添加技术学习课程资料</code></li></ul>`,22)])])}const u=i(n,[["render",o]]);export{g as __pageData,u as default};
